begin;set local search_path=public,extensions;select plan(14);

select ok((select p.prosrc like'%has_platform_role%'and p.prosrc not like'%from public.platform_user_roles%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='list_admin_operations_projection'),'Admin projection uses canonical revocation-aware authorization');
select ok((select p.prosrc like'%provider_company_decisions%'and p.prosrc like'%provider_qualification_decisions%'and p.prosrc like'%provider_capacity_versions%'and p.prosrc like'%provider_document_versions%'and p.prosrc like'%provider_restriction_decisions%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='provider_service_eligibility_snapshot'),'eligibility is derived from versioned provider evidence');


update public.provider_qualifications set current_decision_id='ad300000-0000-4000-8000-000000000001'where id='ad200000-0000-4000-8000-000000000001';

select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->>'eligible')::boolean,'ALLOW runtime: valid versioned evidence is eligible');
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'CAPACITY_FULL','DENY runtime: FULL service capacity');
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'CAPACITY_PAUSED','DENY runtime: PAUSED service capacity');
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'QUALIFICATION_EXPIRED','DENY runtime: expired qualification');
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'QUALIFICATION_NOT_EFFECTIVE','DENY runtime: future qualification is not effective');
update public.provider_qualifications set current_decision_id='ad300000-0000-4000-8000-000000000001'where id='ad200000-0000-4000-8000-000000000001';
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'PARTNER_CONTRACT_INVALID','DENY runtime: expired partner contract');
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'DOCUMENT_LEGAL_INVALID','DENY runtime: expired required company document');
select ok((private.provider_service_eligibility_snapshot('ab000000-0000-4000-8000-000000000002','ac300000-0000-4000-8000-000000000001')->'reasons')?'ACTIVE_HUMAN_RESTRICTION','DENY runtime: active human restriction');

select throws_ok($$insert into public.rfq_providers(rfq_id,provider_organization_id,matching_candidate_id)values('af400000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000002','af300000-0000-4000-8000-000000000001')$$,'23514','RFQ_PROVIDER_NOT_CURRENTLY_ELIGIBLE','DENY runtime: region mismatch');
select throws_ok($$insert into public.rfq_providers(rfq_id,provider_organization_id,matching_candidate_id)values('af400000-0000-4000-8000-000000000002','ab000000-0000-4000-8000-000000000002','af300000-0000-4000-8000-000000000002')$$,'23514','RFQ_PROVIDER_NOT_CURRENTLY_ELIGIBLE','DENY runtime: contact masking disabled');
select throws_ok($$insert into public.rfq_providers(rfq_id,provider_organization_id,matching_candidate_id)values('af400000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000002','af300000-0000-4000-8000-000000000003')$$,'23514','RFQ_PROVIDER_NOT_CURRENTLY_ELIGIBLE','DENY runtime: self-match');
select lives_ok($$insert into public.rfq_providers(rfq_id,provider_organization_id,matching_candidate_id)values('af400000-0000-4000-8000-000000000004','ab000000-0000-4000-8000-000000000002','af300000-0000-4000-8000-000000000004')$$,'ALLOW runtime: valid region, evidence and contact mask');

select * from finish();rollback;
